using var cts = new CancellationTokenSource();
var token = cts.Token;                              // pass this down

await Task.Run(async () => {
    while (true) {
        token.ThrowIfCancellationRequested();       // safe point
        await DoChunkAsync(token);
    }
}, token);

cts.Cancel();                                       // request, not forced termination

using var timeoutCts = new CancellationTokenSource(TimeSpan.FromSeconds(2));
using var linked = CancellationTokenSource.CreateLinkedTokenSource(callerToken, timeoutCts.Token);

await operationAsync(linked.Token);                    // one unified cancellation path

// wait-only semantics instead:
try { await work.WaitAsync(TimeSpan.FromSeconds(2), callerToken); }
catch (TimeoutException) { /* stop waiting, work continues */ }

